const body = $input.item.json.body;
const callback = body.callback_query;
const message = body.message;

let chatId = 0;
let fromId = 0;
let text = '';
let isCallback = false;
let callbackData = '';

if (callback) {
  isCallback = true;
  chatId = callback.message.chat.id;
  fromId = callback.from.id;
  callbackData = callback.data || '';
} else if (message) {
  chatId = message.chat.id;
  fromId = message.from.id;
  text = (message.text || '').trim();
}

const lowerText = text.toLowerCase();
const cmd = callbackData || lowerText;

let directReply = null;

if (cmd === '/start' || cmd === 'menu' || cmd === 'btn_start') {
  directReply = {
    type: 'menu',
    text: '👋 <b>Selamat Datang di EL GROUP AI Assistant!</b>\n\nLayanan resmi informasi & reservasi Spa, Karaoke KTV, dan Club EL Group.\n\nSilakan pilih menu di bawah ini:'
  };
} else if (cmd === '/outlets' || cmd === 'btn_outlets' || cmd.includes('outlet')) {
  directReply = {
    type: 'text',
    text: '📍 <b>DAFTAR OUTLET EL GROUP & GOOGLE MAPS:</b>\n\n1. <b>EL CENTRO</b> (Gajah Mada)\n2. <b>EL SPA PANGJAY</b> (Pangeran Jayakarta)\n3. <b>EL SEVEN CLUB</b> (Gajah Mada) - <a href="https://g.co/kgs/XsooJhR">Google Maps</a>\n4. <b>EL NORTE</b> (PIK) - <a href="https://g.co/kgs/2x2ah1j">Google Maps</a>\n5. <b>EL FENIX</b> (Kelapa Gading)\n6. <b>EL SPA GADING</b> (Kelapa Gading) - <a href="https://g.co/kgs/boEFS4t">Google Maps</a>\n7. <b>EL ORCA</b> (GLC) - <a href="https://g.co/kgs/uftGAAa">Google Maps</a>\n8. <b>EL CASA</b> (GADSER) - <a href="https://g.co/kgs/JbtEvHK">Google Maps</a>\n9. <b>EL MEMENTO</b> (JAKSEL) - <a href="https://share.google/NkCFC2E5gQHcVXI7Y">Google Maps</a>'
  };
} else if (cmd === '/jamops' || cmd === 'btn_jamops' || cmd.includes('jam ops')) {
  directReply = {
    type: 'text',
    text: '⏰ <b>JAM OPERASIONAL OUTLET EL GROUP:</b>\n\n📍 <b>El Centro:</b> 14.00 - 01.00 | Last Order 00.30\n📍 <b>El Spa Pangjay:</b> 12.00 - 23.00 | Last Order 22.30\n📍 <b>El Seven Club:</b> 18.00 - 04.00 | Last Order 03.30\n📍 <b>El Norte:</b> 12.00 - 24.00 | Last Order 23.30\n📍 <b>El Fenix:</b> 14.00 - 24.00 | Last Order 23.30\n📍 <b>El Spa KG:</b> 12.00 - 23.00 | Last Order 22.30\n📍 <b>El Orca:</b> 12.00 - 23.00 | Last Order 22.30\n📍 <b>El Casa:</b> 13.00 - 24.00 | Last Order 23.30\n📍 <b>El Memento:</b> 12.00 - 01.00 | Last Order 00.30\n\n✨ <i>Buka Setiap Hari!</i>'
  };
} else if (cmd === '/pricelist' || cmd === '/ktv' || cmd === '/celeb' || cmd === 'btn_pricelist' || cmd.includes('harga') || cmd.includes('paket')) {
  directReply = {
    type: 'text',
    text: '💎 <b>INFORMASI HARGA & PAKET EL GROUP:</b>\n\n🔥 <b>PAKET ESTAFET:</b> 90 menit (3x FJ), 3 Ladies Platinum.\n💦 <b>PAKET THREESOME:</b> Durasi 1-2 Jam (Voucher Kamar).\n🎰 <b>DOUBLE JACKPOT:</b> 60 menit (1x FJ + 1x HJ, Khusus El Seven).\n🎤 <b>KARAOKE KTV & PARTY:</b> Regular (3 Jam), Party (4 Jam), Pool Spa (4 Jam), Close Voucher.\n⭐ <b>BOOKING CELEB:</b> Wajib H-1, DP 50%.\n\n<i>* Detail harga tepat sesuai cabang yang ingin dikunjungi.</i>'
  };
} else if (cmd === '/member' || cmd === 'btn_member' || cmd.includes('member')) {
  directReply = {
    type: 'text',
    text: '🪪 <b>REGISTRASI MEMBER EL GROUP:</b>\n\nKirim format registrasi ke Telegram @MadamTika:\n- Nama Member: (Bebas)\n- No HP: (Aktif)\n\n✨ <b>Keuntungan:</b> Dapat dipakai di seluruh outlet EL Group + Cashback Top Up!\n🌐 Digital Card: <a href="https://app.elgroupapp.com/">elgroupapp.com</a>'
  };
} else if (cmd === '/booking' || cmd === 'btn_booking' || cmd.includes('booking')) {
  directReply = {
    type: 'text',
    text: '📞 <b>KONTAK RESERVASI & BOOKING RESMI:</b>\n\n👑 <b>Booking Umum / Outlet Lain:</b>\nMadam Tika (WhatsApp: https://wa.me/qr/O6QEVDUNDJB4G1 | Telegram: @MadamTika)\n\n🌴 <b>Booking EL NORTE:</b>\nKim Asst Norte (WhatsApp: https://wa.me/qr/XQRRH3QXZCZAA1 | Telegram: @kimasst)\n\n🔥 <b>Booking EL FENIX:</b>\nDori Asst Fenix (WhatsApp: https://wa.me/qr/KSTLRQATOQ2PC1 | Telegram: @Doriasst)'
  };
}

return {
  chatId,
  fromId,
  text,
  isCallback,
  callbackData,
  isDirect: directReply !== null,
  directReply
};
